class Solution:
    def lcaDeepestLeaves(self, root):
        def dfs(node):
            if not node:
                return 0, None
            ld, ll = dfs(node.left)
            rd, rl = dfs(node.right)
            if ld == rd:
                return ld + 1, node
            elif ld > rd:
                return ld + 1, ll
            else:
                return rd + 1, rl
        return dfs(root)[1]

